import{_ as a,o as i,c as s,a0 as n}from"./chunks/framework.DYS8d9tm.js";const u=JSON.parse('{"title":"Full System Backup & Restore Architecture (.wfam)","description":"","frontmatter":{},"headers":[],"relativePath":"technical/architecture/backup_restore.md","filePath":"technical/architecture/backup_restore.md"}'),t={name:"technical/architecture/backup_restore.md"};function o(r,e,d,c,l,p){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="full-system-backup-restore-architecture-wfam" tabindex="-1">Full System Backup &amp; Restore Architecture (<code>.wfam</code>) <a class="header-anchor" href="#full-system-backup-restore-architecture-wfam" aria-label="Permalink to &quot;Full System Backup &amp; Restore Architecture (\`.wfam\`)&quot;">​</a></h1><p>The standalone backup module (<code>Backend/app/modules/backup/</code>) implements server-independent, ID-less full workspace export and priority-preserving merge restore.</p><hr><h2 id="wfam-binary-container-specification-v1" tabindex="-1"><code>.wfam</code> Binary Container Specification (v1) <a class="header-anchor" href="#wfam-binary-container-specification-v1" aria-label="Permalink to &quot;\`.wfam\` Binary Container Specification (v1)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Offset   Size       Field</span></span>
<span class="line"><span>------   --------   -------------------------------------------------------</span></span>
<span class="line"><span>0        5 bytes    Magic header: b&quot;WFAM\\x01&quot;</span></span>
<span class="line"><span>5        1 byte     Encryption flag:</span></span>
<span class="line"><span>                      0x00 = Unencrypted ZIP payload</span></span>
<span class="line"><span>                      0x01 = Passphrase-encrypted streaming AES-256-GCM</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- Present only when flag == 0x01 ---</span></span>
<span class="line"><span>6        16 bytes   Random PBKDF2 salt</span></span>
<span class="line"><span>22       4 bytes    PBKDF2-HMAC-SHA256 iterations (uint32 big-endian, default 600,000)</span></span>
<span class="line"><span>26       12 bytes   Random 96-bit base IV</span></span>
<span class="line"><span>38       variable   Stream of 64 KB chunks:</span></span>
<span class="line"><span>                      [4 bytes uint32 big-endian chunk_len]</span></span>
<span class="line"><span>                      [ciphertext + 16-byte GCM authentication tag]</span></span></code></pre></div><h3 id="chunk-authentication-streaming-security" tabindex="-1">Chunk Authentication &amp; Streaming Security <a class="header-anchor" href="#chunk-authentication-streaming-security" aria-label="Permalink to &quot;Chunk Authentication &amp; Streaming Security&quot;">​</a></h3><ul><li>Each 64 KB chunk derives a unique 96-bit nonce by XORing <code>chunk_index</code> into the last 4 bytes of <code>base_iv</code>.</li><li>Each chunk is authenticated with Associated Authenticated Data (AAD):<div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">struct.pack(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;4sBBI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;WFAM&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> is_final </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, chunk_index)</span></span></code></pre></div>This prevents chunk reordering, silent truncation, and tampering while keeping server RAM usage flat even for multi-hundred-MB Document Vault archives.</li><li><strong>Server-Key Independence</strong>: All ORM <code>EncryptedString</code> / <code>EncryptedText</code> / <code>EncryptedNumeric</code> columns and <code>VaultFileCipher</code> files are decrypted to plaintext before being zipped into the inner archive (<code>manifest.json</code>, <code>data.json</code>, <code>files/&lt;doc_ref&gt;/v&lt;N&gt;</code>), then wrapped with the user&#39;s passphrase. Restoring onto a server with a different <code>SECRET_KEY</code>, <code>Tenant DEK</code>, or <code>BlindIndex</code> key works seamlessly.</li></ul><hr><h2 id="id-less-portable-reference-remapping" tabindex="-1">ID-Less Portable Reference Remapping <a class="header-anchor" href="#id-less-portable-reference-remapping" aria-label="Permalink to &quot;ID-Less Portable Reference Remapping&quot;">​</a></h2><p>Database primary keys (<code>id</code>) and <code>tenant_id</code> are never relied upon across servers:</p><ol><li><strong>Export (<code>_RefRegistry</code>)</strong>: Every primary key is replaced with a sequential portable ref (<code>usr_1</code>, <code>acc_1</code>, <code>cat_1</code>, <code>txn_1</code>, <code>doc_1</code>, <code>loan_1</code>, <code>goal_1</code>, <code>mfh_1</code>, <code>stmt_1</code>, <code>rule_1</code>, <code>ecfg_1</code>, <code>eslog_1</code>, <code>eg_1</code>). Zero raw UUIDs are written to <code>data.json</code>.</li><li><strong>Import (<code>id_map</code>)</strong>: Every inserted record receives a fresh <code>uuid.uuid4()</code>. All foreign keys and self-referencing columns (<code>categories.parent_id</code>, <code>transactions.linked_transaction_id</code>, <code>document_vault.parent_id</code>) are remapped via two-pass resolution.</li><li><strong>Blind Indexes &amp; Re-encryption</strong>: Writing through ORM hybrid setters (<code>User.email</code>, <code>User.pan_number</code>, <code>User.phone_number</code>, <code>Account.account_number</code>) automatically computes new blind indexes and encrypts values under the target tenant&#39;s active DEK.</li></ol><hr><h2 id="priority-preserving-merge-semantics" tabindex="-1">Priority-Preserving Merge Semantics <a class="header-anchor" href="#priority-preserving-merge-semantics" aria-label="Permalink to &quot;Priority-Preserving Merge Semantics&quot;">​</a></h2><p>By default (<code>mode=&quot;merge&quot;</code>), import <strong>never wipes existing data</strong> on the target server. Existing records on the new server take highest priority:</p><ul><li><strong>Tenant Settings</strong>: Existing <code>(tenant_id, key)</code> kept untouched; missing keys inserted.</li><li><strong>Categories</strong>: Matched by <code>(name, type)</code>; existing category preserved and mapped in <code>id_map</code>.</li><li><strong>Accounts &amp; 1-to-1 Extensions</strong>: Matched by <code>(name, type)</code> or <code>(account_mask, type)</code>; existing account and its credit card / FD / PF / loan details are preserved and mapped in <code>id_map</code>.</li><li><strong>Transactions</strong>: Deduplicated by <code>content_hash</code> or <code>(account_id, date, amount, type, description)</code>.</li><li><strong>Budgets, Expense Groups, Mutual Fund Holdings, Email Configurations</strong>: Deduplicated by natural keys so new-server state always wins.</li><li><strong>Schema Evolution Tolerance</strong>: Major version is checked (<code>1.x</code>), missing optional fields default cleanly, unknown keys are ignored, and unknown enum values fall back safely.</li></ul><hr><h2 id="security-operational-hardening" tabindex="-1">Security &amp; Operational Hardening <a class="header-anchor" href="#security-operational-hardening" aria-label="Permalink to &quot;Security &amp; Operational Hardening&quot;">​</a></h2><ul><li><strong>Role Guard</strong>: Only <code>OWNER</code> and <code>ADULT</code> roles may call <code>/api/v1/backup/*</code>. <code>CHILD</code> and <code>GUEST</code> receive HTTP <code>403</code>.</li><li><strong>Email Verification</strong>: <code>current_user.email</code> (normalized) must match an email in <code>manifest.member_emails</code> (owner or any family member); otherwise HTTP <code>403</code> is returned before any database mutation.</li><li><strong>Zip-Slip &amp; Zip-Bomb Protection</strong>: Archive entries containing <code>..</code> or absolute paths are rejected; compressed upload ceiling is <code>512 MB</code> and uncompressed ceiling is <code>1 GB</code>.</li><li><strong>DB + Filesystem Atomicity</strong>: Restored Vault files are written into freshly generated <code>new_doc_id</code> directories; on any failure, the DB transaction rolls back and newly created files are cleaned up without touching pre-existing files.</li><li><strong>Client-Side ZK Files (<code>WFZK01</code>)</strong>: Preserved as ciphertext with an explicit warning in <code>manifest.warnings</code>.</li></ul><h3 id="nginx-reverse-proxy-sizing" tabindex="-1">Nginx / Reverse Proxy Sizing <a class="header-anchor" href="#nginx-reverse-proxy-sizing" aria-label="Permalink to &quot;Nginx / Reverse Proxy Sizing&quot;">​</a></h3><p>If serving WealthFam behind Nginx and backing up large Document Vaults, ensure your proxy configuration allows large <code>.wfam</code> uploads and sufficient request timeouts:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /api/v1/backup/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    client_max_body_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">512M</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_read_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_send_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="api-endpoints" tabindex="-1">API Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/backup/export</code></td><td>Streams a <code>.wfam</code> download (<code>passphrase</code>, <code>encrypt=true</code>, <code>include_vault_files=true</code>).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/backup/inspect</code></td><td>Multipart upload (<code>file</code>, <code>passphrase</code>); returns manifest summary &amp; email verification status without modifying DB.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/backup/import</code></td><td>Multipart upload (<code>file</code>, <code>passphrase</code>, <code>mode=&quot;merge&quot;</code>); verifies email and merges all records + Vault files with fresh IDs.</td></tr></tbody></table>`,24)])])}const g=a(t,[["render",o]]);export{u as __pageData,g as default};
